def gateway_error_rate() -> float:
    """Share of charges that should fail (0.0 when off)."""
    value = setting("SHOPLITE_FAULT_GATEWAY_ERRORS")
    if value in OFF_VALUES:
        return 0.0
    if value in ON_VALUES:
        return 1.0
    return min(1.0, max(0.0, float(value)))

