import os
from flask import Flask, g
from warehouse import ops
from warehouse.api import api_bp, error

def create_app(overrides: dict | None = None) -> Flask:
    """Build the warehouse app."""
    app = Flask(__name__)
    app.config.update(load_config(overrides))
    db_dir = os.path.dirname(app.config["WAREHOUSE_DB_PATH"])
    if db_dir:
        os.makedirs(db_dir, exist_ok=True)
    ops.init_app(app)
    app.register_blueprint(api_bp)

    @app.teardown_appcontext
    def close_db(_exc):
        """Close the request's database connection."""
        conn = g.pop("db", None)
        if conn is not None:
            conn.close()

    @app.errorhandler(404)
    def not_found(_err):
        """Unknown routes as JSON."""
        return error("WH-HTTP-404", "not found", 404)

    @app.errorhandler(405)
    def method_not_allowed(_err):
        """Wrong method as JSON."""
        return error("WH-HTTP-405", "method not allowed", 405)

    return app

